updated_at` from (((((((((((`app_accompaniment` join `app_schedule_student` on(((`app_accompaniment`.`schedule_student_id` = `app_schedule_student`.`schedule_student_id`) and (`app_accompaniment`.`semester_id` = `app_schedule_student`.`semester_id`)))) join `app_students` on((`app_students`.`student_id` = `app_schedule_student`.`student_id`))) join `app_majors` `major` on((`major`.`majors_id` = `app_students`.`majors_id`))) join `app_faculties` `faculty` on((`faculty`.`faculty_id` = `major`.`faculty_id`))) join `aplego_user` `user_difabel` on((`user_difabel`.`user_id` = `app_students`.`user_id`))) join `app_students` `student_volunteer` on((`student_volunteer`.`student_id` = `app_accompaniment`.`volunteer_id`))) join `aplego_user` `user_volunteer` on((`user_volunteer`.`user_id` = `student_volunteer`.`user_id`))) join `app_students` `data_difabel` on((`data_difabel`.`student_id` = `app_accompaniment`.`schedule_student_id`))) join `aplego_user_meta` on((`aplego_user_meta`.`user_id` = `data_difabel`.`user_id`))) join `app_majors` `major_volunteer` on((`major_volunteer`.`majors_id` = `student_volunteer`.`majors_id`))) join `app_faculties` `faculty_volunteer` on((`faculty_volunteer`.`faculty_id` = `major_volunteer`.`faculty_id`))) order by `app_accompaniment`.`date`,`app_schedule_student`.`start_at` ;

