CREATE ALGORITHM=UNDEFINED     VIEW `app_chart_accompainiment_pendampingan_view`  AS  select `app_accompaniment`.`semester_id` AS `semester_id`,`app_schedule_student`.`student_id` AS `student_id`,date_format(`app_accompaniment`.`date`,'%Y-%m') AS `date`,sum(if((isnull(`app_accompaniment`.`student_status`) or (`app_accompaniment`.`student_status` = 'terjadwal')),1,0)) AS `terjadwal`,sum(if((isnull(`app_accompaniment`.`student_status`) or (`app_accompaniment`.`student_status` = 'Dilihat')),1,0)) AS `belum_datang`,sum(if((`app_accompaniment`.`student_status` = 'Hadir'),1,0)) AS `selesai`,sum(if((`app_accompaniment`.`student_status` = 'Izin'),1,0)) AS `izin`,sum(if((`app_accompaniment`.`student_status` = 'Tidak Didampingi'),1,0)) AS `tidak_datang` from (`app_accompaniment` join `app_schedule_student` on((`app_accompaniment`.`schedule_student_id` = `app_schedule_student`.`schedule_student_id`))) group by `app_accompaniment`.`semester_id`,`app_schedule_student`.`student_id`,date_format(`app_accompaniment`.`date`,'%Y-%m') ;

